package com.lbos.commercecustomer.controller; import com.lbos.commercecustomer.dto.request.*;import com.lbos.commercecustomer.dto.response.*;import com.lbos.commercecustomer.service.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.time.OffsetDateTime;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/customers/me/addresses") public class AddressController {private final AddressService service;public AddressController(AddressService s){service=s;}private <T> ApiResponse<T> ok(HttpServletRequest r,String m,T d){return ApiResponse.of(Optional.ofNullable(r.getHeader("X-Correlation-Id")).orElse("not-provided"),m,d);}@PostMapping public ResponseEntity<ApiResponse<AddressResponse>> create(@Valid @RequestBody AddressRequest r,HttpServletRequest h){return ResponseEntity.status(201).body(ok(h,"Address created",service.create(r)));}@GetMapping("/{id}") public ApiResponse<AddressResponse> get(@PathVariable UUID id,HttpServletRequest h){return ok(h,"Address retrieved",service.get(id));}@GetMapping public ApiResponse<PageResponse<AddressResponse>> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,HttpServletRequest h){return ok(h,"Addresses retrieved",service.list(page,size));}@PatchMapping("/{id}") public ApiResponse<AddressResponse> update(@PathVariable UUID id,@Valid @RequestBody AddressRequest r,HttpServletRequest h){return ok(h,"Address updated",service.update(id,r));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){service.delete(id);}@GetMapping("/default") public ApiResponse<AddressResponse> def(HttpServletRequest h){return ok(h,"Default address retrieved",service.defaultAddress());}@PutMapping("/{id}/default") public ApiResponse<AddressResponse> set(@PathVariable UUID id,HttpServletRequest h){return ok(h,"Default address updated",service.setDefault(id));}}